import zipfile
import re
import xml.etree.ElementTree as ET

NS = {
    "main": "http://schemas.openxmlformats.org/spreadsheetml/2006/main",
    "rel": "http://schemas.openxmlformats.org/officeDocument/2006/relationships",
    "pkgrel": "http://schemas.openxmlformats.org/package/2006/relationships",
}

def col_to_idx(ref):
    m = re.match(r"([A-Z]+)(\d+)", ref)
    letters, row = m.group(1), int(m.group(2))
    idx = 0
    for ch in letters:
        idx = idx * 26 + (ord(ch) - ord("A") + 1)
    return idx - 1, row  # 0-based col, 1-based row

def get_text(el):
    return "".join(el.itertext())

path = "budget.xlsx"
with zipfile.ZipFile(path) as z:
    names = z.namelist()
    print("Archive entries:", names)

    wb_xml = ET.fromstring(z.read("xl/workbook.xml"))
    sheets = [(s.get("name"), s.get("{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id"))
              for s in wb_xml.find("main:sheets", NS)]
    print("Sheets:", sheets)

    shared = []
    if "xl/sharedStrings.xml" in names:
        ss = ET.fromstring(z.read("xl/sharedStrings.xml"))
        for si in ss.findall("main:si", NS):
            shared.append(get_text(si))

    rels = ET.fromstring(z.read("xl/_rels/workbook.xml.rels"))
    relmap = {r.get("Id"): r.get("Target") for r in rels.findall("pkgrel:Relationship", NS)}

    for name, rid in sheets:
        target = relmap[rid]
        if target.startswith("/"):
            target = target[1:]
        else:
            target = "xl/" + target
        ws = ET.fromstring(z.read(target))
        rows = {}
        for c in ws.iter("{%s}c" % NS["main"]):
            ref = c.get("r")
            if ref is None:
                continue
            col, row = col_to_idx(ref)
            t = c.get("t")
            v = c.find("main:v", NS)
            if t == "s" and v is not None:
                val = shared[int(v.text)]
            elif t == "inlineStr":
                val = get_text(c.find("main:is", NS))
            elif t == "str" and v is not None:
                val = v.text
            elif v is not None:
                val = v.text
            else:
                val = None
            rows.setdefault(row, {})[col] = val
        print(f"\n--- Sheet: {name} ---")
        if rows:
            maxrow = max(rows)
            maxcol = max(max(c for c in r) for r in rows.values())
            for r in range(1, maxrow + 1):
                line = []
                for c in range(maxcol + 1):
                    line.append(rows.get(r, {}).get(c, ""))
                print(r, line)
        else:
            print("(empty)")

import zipfile
import re
import xml.etree.ElementTree as ET

NS = {"main": "http://schemas.openxmlformats.org/spreadsheetml/2006/main"}

def col_to_idx(ref):
    m = re.match(r"([A-Z]+)(\d+)", ref)
    letters = m.group(1)
    idx = 0
    for ch in letters:
        idx = idx * 26 + (ord(ch) - ord("A") + 1)
    return idx - 1, int(m.group(2))

with zipfile.ZipFile("budget.xlsx") as z:
    ss = ET.fromstring(z.read("xl/sharedStrings.xml"))
    shared = ["".join(si.itertext()) for si in ss.findall("main:si", NS)]
    ws = ET.fromstring(z.read("xl/worksheets/sheet1.xml"))

    grid = {}
    for c in ws.iter("{%s}c" % NS["main"]):
        ref = c.get("r")
        if not ref:
            continue
        col, row = col_to_idx(ref)
        v = c.find("main:v", NS)
        if c.get("t") == "s" and v is not None:
            val = shared[int(v.text)]
        elif v is not None:
            val = v.text
        else:
            val = None
        grid.setdefault(row, {})[col] = val

# Locate EXPENSES header row and Total Expenses row
exp_start = total_row = None
for r in sorted(grid):
    a = grid[r].get(0)
    if a == "EXPENSES":
        exp_start = r + 1
    elif a == "Total Expenses":
        total_row = r
print("EXPENSES section rows:", exp_start, "to", total_row - 1)

by_category = {}
grand_total = 0.0
for r in range(exp_start, total_row):
    cat = grid[r].get(0)
    amt = grid[r].get(2)
    if amt is None:
        continue
    amt = float(amt)
    grand_total += amt
    by_category[cat] = by_category.get(cat, 0.0) + amt

for cat, total in by_category.items():
    print(f"  {cat}: ${total:,.2f}")
print(f"TOTAL EXPENSES: ${grand_total:,.2f}")

